  function unit(value,unitName){
    var n=Number(value)||0;
    return new Intl.NumberFormat(locale(),{style:"unit",unit:unitName,unitDisplay:"long"}).format(n);
  }
  function duration(ms){
    ms=Number(ms)||0;if(ms<=0)return t("timeNotRecorded");
    var sec=Math.floor(ms/1000),min=Math.floor(sec/60);sec%=60;var h=Math.floor(min/60);min%=60;
    var parts=[];
    if(h)parts.push(unit(h,"hour"));
    if(min)parts.push(unit(min,"minute"));
    if(!h&&!min&&sec)parts.push(unit(sec,"second"));
    if(parts.length===1)return parts[0];
    if(typeof Intl.ListFormat==="function")return new Intl.ListFormat(locale(),{style:"short",type:"conjunction"}).format(parts);
    return parts.join(" ");
  }
